using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckDockDiving {
public sealed class DockSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> results=new List<string>();Keyboard keyboard;InputSettings original,probe;DockMatch match;string folder;bool done,error;int[] caseDistances=new int[6];
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsDock")<0)return;var g=new GameObject("Dock Diving native physics and replay validation");DontDestroyOnLoad(g);g.AddComponent<DockSmoke>();}
 SportsTestPreferences preferences;void Start(){preferences=new SportsTestPreferences();folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../DockEvidence"));Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Dock software keyboard");Keys();Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;results.Add("ERROR "+s);}}
 void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}
 void Check(bool condition,string label){if(!condition)throw new Exception(label);results.Add("PASS "+label);Debug.Log("DOCK_NATIVE_PASS "+label);}void Note(string s){results.Add(s);Debug.Log("DOCK_NATIVE_EVIDENCE "+s);}
 IEnumerator Delay(float t){float end=Time.realtimeSinceStartup+t;while(Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Wait(Func<bool> predicate,float timeout,string label){float end=Time.realtimeSinceStartup+timeout;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label+" phase="+match?.Phase+" truck="+match?.truck.body.position);yield return null;}}
 void Update(){if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){results.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;preferences?.Dispose();Time.timeScale=1;Keys();if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);File.WriteAllLines(Path.Combine(folder,"results.txt"),results);Application.Quit(code);}
 void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SceneManager.LoadScene("TruckDockDiving");yield return Delay(.6f);match=FindAnyObjectByType<DockMatch>();Check(match!=null&&match.staged.Length==8,"saved Dock Diving scene and eight staging trucks");Check(match.replay.ghost.GetComponentsInChildren<Collider>(true).Length==0,"replay ghosts have no collision geometry");
  float[] timing={4,2,.6f,-.8f,-99,.6f};for(int i=0;i<timing.Length;i++)yield return PhysicalAttempt(i,timing[i],i==5?.5f:1);
  Check(caseDistances[2]>caseDistances[5]+12,"higher physical approach speed increases distance at same timing");
  match.SetupScreen();match.setup.count=8;for(int i=0;i<8;i++){match.setup.players[i].source=BowlingSource.AI;match.setup.players[i].difficulty=(BowlingDifficulty)(i%3);match.setup.players[i].name="Competitor "+(i+1);}match.AllBots();Check(match.StartMatch(),"eight-AI full match starts");Time.timeScale=4;yield return Wait(()=>match.Finished,300,"complete eight-AI match including recorded replays");Check(match.CompletedAttempts>=24&&match.Locks==match.CompletedAttempts&&match.Launches==match.CompletedAttempts,"three attempts per competitor, one launch/score lock each");int valid=0;for(int i=0;i<8;i++){string line="Dock AI "+match.setup.players[i].difficulty+" slot="+i+" best="+match.best[i]+"in attempts=";for(int j=0;j<3;j++){line+=match.history[i,j]+"in ";if(match.history[i,j]>0)valid++;}Note(line);}Check(valid>=16,"AI physically reaches the pool in most attempts without forced scores");Check(match.Winner>=0&&match.Winner<8,"final winner resolved");Time.timeScale=1;Capture("eight-ai-results");yield return Delay(.2f);
  match.SetupScreen();Screen.SetResolution(1280,720,false);yield return Delay(.4f);Capture("setup-eight-720");yield return Delay(.2f);Screen.SetResolution(1920,1080,false);yield return Delay(.4f);Capture("setup-eight-1080");yield return Delay(.2f);Check(match.StartMatch(),"rematch retains eight participants");yield return Delay(.3f);match.Pause();var p=match.truck.body.position;yield return Delay(.25f);Check(match.truck.body.position==p&&match.Paused,"pause preserves active attempt body");match.Resume();yield return Delay(.2f);Check(match.Live,"resume preserves match");SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"repeated collection return cleans scene-owned replay/cameras/audio");}
 IEnumerator PhysicalAttempt(int index,float remaining,float gas){Keys();match.SetupScreen();match.setup.count=1;match.setup.players[0].source=BowlingSource.Keyboard;match.setup.players[0].name="Physical probe";Check(match.StartMatch(),"physical timing attempt "+index+" starts");yield return Delay(.25f);bool pressed=false;float until=Time.realtimeSinceStartup+35;while(match.Phase==DockPhase.Approach){float distance=match.edge-(match.truck.body.position.z+1.4f);if(!pressed&&distance<=remaining){Keys(Key.W,Key.Space);pressed=true;}else if(!pressed){if(gas>.9f||Mathf.Repeat(Time.realtimeSinceStartup,.1f)<gas*.1f)Keys(Key.W);else Keys();}else Keys(Key.W);if(Time.realtimeSinceStartup>until)throw new Exception("Dock physical approach stalled");yield return null;}Keys();Check(match.Launches==1,"actual input or automatic edge launches once "+index);string expected=index==0?"EARLY":index==1?"GOOD":index==2||index==5?"PERFECT":index==3?"LATE":"MISSED · AUTO";Check(match.Timing==expected,"physical timing quality "+expected+" actual="+match.Timing);if(index==2){yield return Delay(.25f);Capture("actual-launch-split");yield return Delay(.2f);match.Pause();var p=match.truck.body.position;var v=match.truck.body.linearVelocity;yield return Delay(.3f);Check(match.truck.body.position==p&&match.truck.body.linearVelocity==v,"pause during real flight preserves momentum");match.Resume();}
  yield return Wait(()=>match.Phase==DockPhase.Replay,12,"physical splash aftermath to replay");int locked=match.LastInches;caseDistances[index]=locked;Check(match.Locks==1,"first contact measured once "+index);Check(match.PersonalBest==PlayerPrefs.GetInt(DockMatch.RecordKey)&&match.PersonalBest>=locked,"solo record uses the same stored inch measurement "+index);match.TouchWater();Check(match.LastInches==locked&&match.Locks==1,"repeated water callback cannot rescore "+index);yield return Delay(1.1f);match.ExtraAction("replayangle");int chosenAngle=match.replay.Angle;yield return Delay(.2f);Check(match.replay.Angle==chosenAngle,"manual camera choice persists without changing speed "+index);match.ExtraAction("replayspeed");match.ExtraAction("replayrewind");Check(match.replay.Playing&&match.LastInches==locked&&match.Locks==1,"camera/rate/rewind are nonphysical "+index);if(index==2){while(Mathf.Abs(match.replay.Speed-.25f)>.001f)match.replay.NextSpeed();Check(!match.replay.Tick(20,false)&&match.replay.Playing,"manual quarter-speed replay survives old16second automatic cap");match.replay.Rewind();match.actions[match.Active]=true;match.menus.Action("replayangle");yield return Delay(.15f);Check(match.Phase==DockPhase.Replay,"replay UI consumes pending gameplay action edge");while(Mathf.Abs(match.replay.Speed-2)>.001f)match.replay.NextSpeed();yield return Delay(1.6f);Capture("physical-flight-replay");yield return Delay(.2f);}match.ExtraAction("replayskip");Check(match.Phase==DockPhase.Result,"replay skip advances cleanly "+index);Note("PHYSICAL timing="+match.Timing+" inches="+locked+" frames="+match.replay.Count+" bodyPosition="+match.truck.body.position);Keys();}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
